const ss=await figma.importComponentSetByKeyAsync('c0f91fc11bf2c0abd7d232c02d111a133b0a478a');
const src=ss.children.find(n=>n.name==='State=Enabled, Show avatar=False');
const allTexts=base.findAllWithCriteria({types:['TEXT']}).concat(src.findAllWithCriteria({types:['TEXT']}));
const fonts=[...new Map(allTexts.flatMap(t=>t.getStyledTextSegments(['fontName']).map(s=>[JSON.stringify(s.fontName),s.fontName]))).values()];
await Promise.all(fonts.map(f=>figma.loadFontAsync(f)));
const roots=[],notes=[];
function paint(h){return [{type:'SOLID',color:{r:parseInt(h.slice(1,3),16)/255,g:parseInt(h.slice(3,5),16)/255,b:parseInt(h.slice(5,7),16)/255}}];}
function al(parent,name,dir,w,h,bg,gap=0){const n=figma.createAutoLayout(dir);parent.appendChild(n);n.name=name;n.resize(w,h);n.primaryAxisSizingMode='FIXED';n.counterAxisSizingMode='FIXED';n.itemSpacing=gap;n.fills=bg?paint(bg):[];return n;}
function txt(parent,s,size,style,color,w,h){const n=figma.createText();parent.appendChild(n);n.fontName={family:'Roboto',style};n.fontSize=size;n.lineHeight={unit:'PIXELS',value:size===18?28:size===11?16:20};n.fills=paint(color);n.textAutoResize='NONE';n.resize(w,h);n.characters=s;n.name=s;return n;}
function ico(parent,name,color,size,path){const n=figma.createNodeFromSvg('<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="'+color+'" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'+path+'</svg>');parent.appendChild(n);n.resize(size,size);n.name=name;return n;}
const opts=[
{num:6,label:'Busca aberta ou limpa',note:'HU3 · Limpar exibe todos; fechar retorna à tela Início',query:''},
{num:7,label:'Busca com resultados',note:'HU3 · “P” encontra títulos com “p”, sem diferenciar caixa',query:'P'},
{num:8,label:'Busca sem resultado',note:'HU3 · Nenhum resultado encontrado',query:'Esperança'}
];
for(const o of opts){
const r=base.clone();p.appendChild(r);r.name=String(o.num).padStart(2,'0')+' · '+o.label;r.x=100+((o.num-1)%4)*404;r.y=820;roots.push(r);
const cap=txt(p,r.name,18,'Bold','#4F378B',344,28);cap.x=r.x;cap.y=r.y-66;notes.push(cap);
const note=txt(p,o.note,11,'Regular','#69636F',344,32);note.x=r.x;note.y=r.y-34;notes.push(note);
r.children.find(n=>n.name==='Barra superior').remove();
const bar=al(r,'Barra superior · busca','HORIZONTAL',344,56,'#4F378B');r.insertChild(0,bar);bar.paddingLeft=12;bar.paddingTop=4;
const wrap=figma.createFrame();bar.appendChild(wrap);wrap.name='Campo de busca';wrap.resize(320,48);wrap.fills=[];
const s=src.createInstance();wrap.appendChild(s);s.name='Busca · Material 3';s.resize(320,48);s.fills=paint('#FFFFFF');
for(const name of ['Leading-icon','1st trailing-icon','2nd trailing-icon']){
const target=s.findOne(n=>n.name===name);if(target)target.visible=false;
}
const layer=s.findOne(n=>n.name==='state-layer');if(layer&&layer.type==='FRAME'){layer.paddingLeft=44;layer.paddingRight=40;}
const hint=s.findAllWithCriteria({types:['TEXT']}).find(n=>n.name==='supporting-text');
if(hint){hint.characters=o.query||'Buscar conteúdo';hint.fontSize=14;hint.fills=paint(o.query?'#24212A':'#69636F');}
const back=ico(wrap,'Fechar busca e voltar ao Início','#6750A4',20,'<path d="m14 5-7 7 7 7M7 12h14"/>');back.x=12;back.y=14;
if(o.query){const close=ico(wrap,'Limpar busca','#69636F',18,'<path d="m6 6 12 12M6 18 18 6"/>');close.x=288;close.y=15;}
const content=r.children.find(n=>n.name==='Conteúdo');
if(o.num===7){const videos=content.children.find(n=>n.name==='Grade de vídeos');videos.children[0].remove();}
if(o.num===8){
for(const child of [...content.children])if(child.name!=='Mais em JW.ORG')child.remove();
const e=al(content,'Busca sem resultados','VERTICAL',320,284,null,16);content.insertChild(0,e);e.primaryAxisAlignItems='CENTER';e.counterAxisAlignItems='CENTER';
const circle=al(e,'Símbolo de busca','HORIZONTAL',64,64,'#EEE8F6');circle.cornerRadius=32;circle.primaryAxisAlignItems='CENTER';circle.counterAxisAlignItems='CENTER';ico(circle,'Busca sem resultados','#6750A4',28,'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>');
const t=txt(e,'Nenhum resultado encontrado',15,'Medium','#69636F',290,40);t.textAlignHorizontal='CENTER';t.textAlignVertical='CENTER';
}
}
await roots[0].screenshot({scale:2});await roots[1].screenshot({scale:2});await roots[2].screenshot({scale:2});
return {createdNodeIds:roots.flatMap(r=>[r.id,...r.findAll(()=>true).map(n=>n.id)]).concat(notes.map(n=>n.id)),frames:roots.map(r=>({id:r.id,name:r.name,width:r.width,height:r.height})),totalScreens:p.children.filter(n=>n.type==='FRAME').length};
